using static StrataLint.Scribe.DefinitionDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S0.Certificates.Games;

internal sealed class VersionBOddCountUnderdeterminesDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S0/Certificates/Games/VersionBOddCountUnderdetermines.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
