            Describe.Lean(DescribeId.Create("underdetermined-version-b-pilecount"),
                DeclarationHandle.Create(Prefix + "pileCount"), H("Pile count"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The sum of the seven multiplicities is the number of nonempty piles."))), DescribeRole.Definition),
