            Describe.Lean(DescribeId.Create("underdetermined-version-b-sixsixes-sixsevens"),
                DeclarationHandle.Create(Prefix + "sixSixes_sixSevens"), H("Six sixes and six sevens"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Write s67 for sixSixes_sixSevens. This position has six piles of size six, six of size seven, and no other piles."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("underdetermined-version-b-sixfives-sixsixes-witness"),
