                Blocks(Paragraph(Text("Removing one token from every pile of six sixes and six sevens reaches six fives and six sixes. The starting position is nonempty, so this all-move is legal."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("underdetermined-version-b-sixsixes-sixsevens-witness"),
                DeclarationHandle.Create(Prefix + "sixSixes_sixSevens_witness"), H("The non-losing witness"),
                StatementSource.FromAuthor(F.Disp(F.Seq(
                    Call("pileCount", Id("s67")), F.Eq, F.Sp, Num(12), F.Land, F.Sp,
                    Num(3), F.Le, F.Sp, Call("pileCount", Id("s67")), F.Land, F.Sp,
                    Call("EveryPileExceedsThreshold", Id("s67")), F.Land, F.Sp,
                    Call("oddPiles", Id("s67")), F.Eq, F.Sp, Num(6), F.Land, F.Sp,
                    F.Neg, F.Sp, Call("Losing", Id("s67"))))), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Six sixes and six sevens satisfy the same scope hypotheses and have the same two counts. Their legal all-move reaches the losing witness, so this position is not losing."))), DescribeRole.Theorem),
